// UnmarshalSSZ ssz unmarshals the HelloCommand object
func (h *HelloCommand) UnmarshalSSZ(buf []byte) error {
	var err error
	size := uint64(len(buf))
	if size < 98 {
		return ssz.ErrSize
	}

	tail := buf
	var o5, o6 uint64

	// Field (0) 'Version'
	h.Version = ssz.UnmarshallUint32(buf[0:4])

	// Field (1) 'NetworkID'
	h.NetworkID = ssz.UnmarshallUint32(buf[4:8])

	// Field (2) 'PeerID'
	copy(h.PeerID[:], buf[8:40])

	// Field (3) 'PeerIP'
	copy(h.PeerIP[:], buf[40:56])

	// Field (4) 'PeerPort'
	h.PeerPort = ssz.UnmarshallUint16(buf[56:58])

	// Offset (5) 'ChainMaskList'
	if o5 = ssz.ReadOffset(buf[58:62]); o5 > size {
		return ssz.ErrOffset
	}

	if o5 != 98 {
		return ssz.ErrInvalidVariableOffset
	}

	// Offset (6) 'RootBlockHeader'
	if o6 = ssz.ReadOffset(buf[62:66]); o6 > size || o5 > o6 {
		return ssz.ErrOffset
	}

	// Field (7) 'GenesisRootBlockHash'
	copy(h.GenesisRootBlockHash[:], buf[66:98])

	// Field (5) 'ChainMaskList'
	{
		buf = tail[o5:o6]
		num, err := ssz.DivideInt2(len(buf), 4, 4294967295)
		if err != nil {
			return err
		}
		h.ChainMaskList = ssz.ExtendUint32(h.ChainMaskList, num)
		for ii := 0; ii < num; ii++ {
			h.ChainMaskList[ii] = ssz.UnmarshallUint32(buf[ii*4 : (ii+1)*4])
		}
	}

	// Field (6) 'RootBlockHeader'
	{
		buf = tail[o6:]
		if len(buf) > 4294967295 {
			return ssz.ErrBytesLength
		}
		if cap(h.RootBlockHeader) == 0 {
			h.RootBlockHeader = make([]byte, 0, len(buf))
		}
		h.RootBlockHeader = append(h.RootBlockHeader, buf...)
	}
	return err
}

